  'material.makeOwnAux': ['Detaches it from the catalogue preset (and from other parts that share it).', 'Lo separa del preset del catálogo (y de otras piezas que lo comparten).'],
  'material.params': ['Parameters', 'Parámetros'],
  'material.flatNote': [
    'The Fast preview shows the wood’s rings and pores as the Wood node bakes them: a slice through the front of the parts, projected onto every face; its knots, on each part where Full mode puts them. Full mode and renders draw the wood as it runs through the whole part. Fabric is woven in the Fast preview by the Fabric node where a thread spans at least 2.5 texels of its bake (coarse weaves, small parts), with its fuzz on top; a finer one shows the mean colour of its weave. Full mode and renders weave its threads, at their real size.',
    'La vista Rápida muestra los anillos y poros de la madera como los hornea el nodo Madera: un corte por el frente de las piezas, proyectado en cada cara; sus nudos, en cada pieza donde los pone el modo Completo. El modo Completo y los renders pintan la madera como corre por toda la pieza. La tela se teje en la vista Rápida con el nodo Tela cuando un hilo ocupa al menos 2,5 téxeles de su horneado (tejidos gruesos, piezas pequeñas), con su pelusa encima; una más fina se ve con el color medio de su tejido. El modo Completo y los renders tejen sus hilos, a su tamaño real.',
  ],
