  'material.fullOnly': ['drawn in Full mode and in renders; the Fast preview weaves it only where a thread spans 2.5 texels of its bake, and shows the mean colour otherwise', 'lo pintan el modo Completo y los renders; la vista Rápida lo teje solo donde un hilo ocupa 2,5 téxeles de su horneado, y si no muestra el color medio'],
